#[derive(Clone, Debug, Default, PartialEq)]
pub struct F4BuildingBirth {
    pub settings: PbSettings,
    pub state: PbStation,
    pub supply: Option<PbSupply>,
    pub crew: bool,
    pub damaged: bool,
    pub attacker: Attacker,
}

impl F4BuildingBirth {
    pub const WORDS: usize = 54;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 54] = (&mut row[..54]).try_into().unwrap();
        self.settings.put(&mut row[0..], heap);
        self.state.put(&mut row[26..], heap);
        match &self.supply { Some(v) => { row[39] = 0.0; v.put(&mut row[39 + 1..], heap); } None => { row[39] = 1.0; row[39 + 1..39 + 10].fill(0.0); } }
        row[49] = if self.crew { 1.0 } else { 0.0 };
        row[50] = if self.damaged { 1.0 } else { 0.0 };
        self.attacker.put(&mut row[51..51 + 3], heap);
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 54] = (&row[..54]).try_into().unwrap();
        Self {
            settings: PbSettings::take(&row[0..], heap),
            state: PbStation::take(&row[26..], heap),
            supply: if row[39] == 0.0 { Some(PbSupply::take(&row[39 + 1..], heap)) } else { None },
            crew: row[49] != 0.0,
            damaged: row[50] != 0.0,
            attacker: Attacker::take(&row[51..51 + 3], heap),
        }
    }

}

